import{_ as o,c as i,o as a,j as n,Y as r,t as s}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"gitformat-commit-graph | x-cmd man (git man5) | Git commit-graph format","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitformat-commit-graph - Git commit-graph format","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitformat-commit-graph | x-cmd man (git man5) | Git commit-graph format"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitformat-commit-graph - Git commit-graph format"}]]},"headers":[],"params":{"isMan":true,"man":"gitformat-commit-graph","category":"git man5","desc":"Git commit-graph format"},"relativePath":"git/man5/gitformat-commit-graph.md","filePath":"git/man5/[man].md"}'),h={name:"git/man5/gitformat-commit-graph.md"},c={class:"visually-hidden"};function l(t,e,p,m,u,b){return a(),i("div",null,[n("h1",c,s(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitformat-commit-graph - Git commit-graph format</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$GIT_DIR/objects/info/commit-graph</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$GIT_DIR/objects/info/commit-graphs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The Git commit-graph stores a list of commit OIDs and some associated metadata, including:</p><blockquote><p>·</p><p>The generation number of the commit.</p></blockquote><blockquote><p>·</p><p>The root tree OID.</p></blockquote><blockquote><p>·</p><p>The commit date.</p></blockquote><blockquote><p>·</p><p>The parents of the commit, stored using positional references within the graph file.</p></blockquote><blockquote><p>·</p><p>The Bloom filter of the commit carrying the paths that were changed between the commit and its first parent, if requested.</p></blockquote><p>These positional references are stored as unsigned 32-bit integers corresponding to the array position within the list of commit OIDs. Due to some special constants we use to track parents, we can store at most (1 &lt;&lt; 30) + (1 &lt;&lt; 29) + (1 &lt;&lt; 28) - 1 (around 1.8 billion) commits.</p><h2 id="commit-graph-files-have-the-following-format" tabindex="-1">COMMIT-GRAPH FILES HAVE THE FOLLOWING FORMAT: <a class="header-anchor" href="#commit-graph-files-have-the-following-format" aria-label="Permalink to &quot;COMMIT-GRAPH FILES HAVE THE FOLLOWING FORMAT:&quot;">​</a></h2><p>In order to allow extensions that add extra data to the graph, we organize the body into &quot;chunks&quot; and provide a binary lookup table at the beginning of the body. The header includes certain values, such as number of chunks and hash type.</p><p>All multi-byte numbers are in network byte order.</p><h3 id="header" tabindex="-1">HEADER: <a class="header-anchor" href="#header" aria-label="Permalink to &quot;HEADER:&quot;">​</a></h3><blockquote><pre><code>4-byte signature:
    The signature is: {&#39;C&#39;, &#39;G&#39;, &#39;P&#39;, &#39;H&#39;}
</code></pre></blockquote><blockquote><pre><code>1-byte version number:
    Currently, the only valid version is 1.
</code></pre></blockquote><blockquote><pre><code> 1-byte Hash Version
     We infer the hash length (H) from this value:
1 =&gt; SHA-1
2 =&gt; SHA-256
     If the hash type does not match the repository&#39;s hash algorithm, the
     commit-graph file should be ignored with a warning presented to the
     user.
</code></pre></blockquote><blockquote><pre><code>1-byte number (C) of &quot;chunks&quot;
</code></pre></blockquote><blockquote><pre><code>1-byte number (B) of base commit-graphs
    We infer the length (H*B) of the Base Graphs chunk
    from this value.
</code></pre></blockquote><h3 id="chunk-lookup" tabindex="-1">CHUNK LOOKUP: <a class="header-anchor" href="#chunk-lookup" aria-label="Permalink to &quot;CHUNK LOOKUP:&quot;">​</a></h3><blockquote><pre><code>(C + 1) * 12 bytes listing the table of contents for the chunks:
    First 4 bytes describe the chunk id. Value 0 is a terminating label.
    Other 8 bytes provide the byte-offset in current file for chunk to
    start. (Chunks are ordered contiguously in the file, so you can infer
    the length using the next chunk position if necessary.) Each chunk
    ID appears at most once.
</code></pre></blockquote><blockquote><pre><code>The CHUNK LOOKUP matches the table of contents from
the chunk-based file format, see linkgit:gitformat-chunk[5]
</code></pre></blockquote><blockquote><pre><code>The remaining data in the body is described one chunk at a time, and
these chunks may be given in any order. Chunks are required unless
otherwise specified.
</code></pre></blockquote><h3 id="chunk-data" tabindex="-1">CHUNK DATA: <a class="header-anchor" href="#chunk-data" aria-label="Permalink to &quot;CHUNK DATA:&quot;">​</a></h3><br> **OID Fanout (ID: {O, I, D, F}) (256 \\* 4 bytes)** <blockquote><blockquote><pre><code>The ith entry, F[i], stores the number of OIDs with first
byte at most i. Thus F[255] stores the total
number of commits (N).
</code></pre></blockquote></blockquote><br> **OID Lookup (ID: {O, I, D, L}) (N \\* H bytes)** <blockquote><blockquote><pre><code>The OIDs for all commits in the graph, sorted in ascending order.
</code></pre></blockquote></blockquote><br> **Commit Data (ID: {C, D, A, T }) (N \\* (H + 16) bytes)** <blockquote><blockquote><p>·</p><p>The first H bytes are for the OID of the root tree.</p></blockquote><blockquote><p>·</p><p>The next 8 bytes are for the positions of the first two parents of the ith commit. Stores value 0x70000000 if no parent in that position. If there are more than two parents, the second value has its most-significant bit on and the other bits store an array position into the Extra Edge List chunk.</p></blockquote><blockquote><p>·</p><p>The next 8 bytes store the topological level (generation number v1) of the commit and the commit time in seconds since EPOCH. The generation number uses the higher 30 bits of the first 4 bytes, while the commit time uses the 32 bits of the second 4 bytes, along with the lowest 2 bits of the lowest byte, storing the 33rd and 34th bit of the commit time.</p></blockquote></blockquote><br> **Generation Data (ID: {G, D, A, 2 }) (N \\* 4 bytes) \\[Optional\\]** <blockquote><blockquote><p>·</p><p>This list of 4-byte values store corrected commit date offsets for the commits, arranged in the same order as commit data chunk.</p></blockquote><blockquote><p>·</p><p>If the corrected commit date offset cannot be stored within 31 bits, the value has its most-significant bit on and the other bits store the position of corrected commit date into the Generation Data Overflow chunk.</p></blockquote><blockquote><p>·</p><p>Generation Data chunk is present only when commit-graph file is written by compatible versions of Git and in case of split commit-graph chains, the topmost layer also has Generation Data chunk.</p></blockquote></blockquote><br> **Generation Data Overflow (ID: {G, D, O, 2 }) \\[Optional\\]** <blockquote><blockquote><p>·</p><p>This list of 8-byte values stores the corrected commit date offsets for commits with corrected commit date offsets that cannot be stored within 31 bits.</p></blockquote><blockquote><p>·</p><p>Generation Data Overflow chunk is present only when Generation Data chunk is present and atleast one corrected commit date offset cannot be stored within 31 bits.</p></blockquote></blockquote><br> **Extra Edge List (ID: {E, D, G, E}) \\[Optional\\]** <blockquote><blockquote><pre><code>This list of 4-byte values store the second through nth parents for
all octopus merges. The second parent value in the commit data stores
an array position within this list along with the most-significant bit
on. Starting at that array position, iterate through this list of commit
positions for the parents until reaching a value with the most-significant
bit on. The other bits correspond to the position of the last parent.
</code></pre></blockquote></blockquote><br> **Bloom Filter Index (ID: {B, I, D, X}) (N \\* 4 bytes) \\[Optional\\]** <blockquote><blockquote><p>·</p><p>The ith entry, BIDX[i], stores the number of bytes in all Bloom filters from commit 0 to commit i (inclusive) in lexicographic order. The Bloom filter for the i-th commit spans from BIDX[i-1] to BIDX[i] (plus header length), where BIDX[-1] is 0.</p></blockquote><blockquote><p>·</p><p>The BIDX chunk is ignored if the BDAT chunk is not present.</p></blockquote></blockquote><br> **Bloom Filter Data (ID: {B, D, A, T}) \\[Optional\\]** <blockquote><blockquote><p>·</p><p>It starts with header consisting of three unsigned 32-bit integers:</p><blockquote><p>·</p><p>Version of the hash algorithm being used. We currently only support value 1 which corresponds to the 32-bit version of the murmur3 hash implemented exactly as described in <strong><a href="https://en.wikipedia.org/wiki/MurmurHash#Algorithm" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/MurmurHash#Algorithm</a></strong> and the double hashing technique using seed values 0x293ae76f and 0x7e646e2 as described in <strong><a href="https://doi.org/10.1007/978-3-540-30494-4_26" target="_blank" rel="noreferrer">https://doi.org/10.1007/978-3-540-30494-4_26</a></strong> &quot;Bloom Filters in Probabilistic Verification&quot;</p></blockquote><blockquote><p>·</p><p>The number of times a path is hashed and hence the number of bit positions that cumulatively determine whether a file is present in the commit.</p></blockquote><blockquote><p>·</p><p>The minimum number of bits <em>b</em> per entry in the Bloom filter. If the filter contains <em>n</em> entries, then the filter size is the minimum number of 64-bit words that contain n*b bits.</p></blockquote></blockquote><blockquote><p>·</p><p>The rest of the chunk is the concatenation of all the computed Bloom filters for the commits in lexicographic order.</p></blockquote><blockquote><p>·</p><p>Note: Commits with no changes or more than 512 changes have Bloom filters of length one, with either all bits set to zero or one respectively.</p></blockquote><blockquote><p>·</p><p>The BDAT chunk is present if and only if BIDX is present.</p></blockquote></blockquote><br> **Base Graphs List (ID: {B, A, S, E}) \\[Optional\\]** <blockquote><blockquote><pre><code>This list of H-byte hashes describe a set of B commit-graph files that
form a commit-graph chain. The graph position for the ith commit in this
file&#39;s OID Lookup chunk is equal to i plus the number of commits in all
base graphs.  If B is non-zero, this chunk must exist.
</code></pre></blockquote></blockquote><h3 id="trailer" tabindex="-1">TRAILER: <a class="header-anchor" href="#trailer" aria-label="Permalink to &quot;TRAILER:&quot;">​</a></h3><blockquote><pre><code>H-byte HASH-checksum of all of the above.
</code></pre></blockquote><h2 id="historical-notes" tabindex="-1">HISTORICAL NOTES: <a class="header-anchor" href="#historical-notes" aria-label="Permalink to &quot;HISTORICAL NOTES:&quot;">​</a></h2><p>The Generation Data (GDA2) and Generation Data Overflow (GDO2) chunks have the number <em>2</em> in their chunk IDs because a previous version of Git wrote possibly erroneous data in these chunks with the IDs &quot;GDAT&quot; and &quot;GDOV&quot;. By changing the IDs, newer versions of Git will silently ignore those older chunks and write the new information without trusting the incorrect data.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,59))])}const k=o(h,[["render",l]]);export{f as __pageData,k as default};
